nction testPlayerStat(%cl) { %pl = Client::getOwnedObject(%cl); if (!Player::isExposed(%cl) || !$matchStarted || $loadingMission || %pl.driver || $missionComplete) return 0; else return 1; } function remoteBuyFavorites(%client,%favItem0,%favItem1,%favItem2,%favItem3,%favItem4,%favItem5,%favItem6,%favItem7,%favItem8,%favItem9,%favItem10,%favItem11,%favItem12,%favItem13,%favItem14,%favItem15,%favItem16,%favItem17,%favItem18,%favItem19) { if (isPlayerBusy(%client) || !testPlayerStat(%client)) return; %time = getIntegerTime(true) >> 4; if(%time <= %client.lastBuyFavTime) return; %client.lastBuyFavTime = %time; %station = (Client::getOwnedObject(%client)).Station; if(%station != "" ) { %stationName = GameBase::getDataName(%station); if(%stationName == DeployableInvStation || %stationName == DeployableAmmoStation) %energy = %station.Energy; else %energy = $TeamEnergy[Client::getTeam(%client)]; if(%energy == "Infinite" || %energy > 0) { %error = 0; %bought = 0; %max = getNumItems(); for (%i = 0; %i < %max; %i = %i + 1) { %item = getItemData(%i); if ($ServerCheats || Client::isItemShoppingOn(%client,%item)|| $TestCheats) { %count = Player::getItemCount(%client,%item); if(%count) { if(%item.className != Armor) teamEnergyBuySell(Client::getOwnedObject(%client),(%item.price * %count)); Player::setItemCount(%client, %item, 0); } } } for (%i = 0; %i < 20; %i++) { if(%favItem[%i] != "") { %item = getItemData(%favItem[%i]); if ((Client::isItemShoppingOn(%client,%item)) && ($ItemMax[Player::getArmor(%client), %item] > Player::getItemCount(%client,%item) || %item.className == Armor)) { if(!buyItem(%client,%item)) %error = 1; else %bought++; } } } if(%bought) { if(%error) Client::sendMessage(%client,0,"~wC_BuySell.wav"); else Client::SendMessage(%client,0,"~wbuysellsound.wav"); } updateBuyingList(%client); } } } function replenishTeamEnergy(%team) { $TeamEnergy[%team] += $incTeamEnergy; schedule("replenishTeamEnergy(" @ %team @ ");", $secTeamEnergy); } function checkResources(%player,%item,%delta,%noMessage) { %client = Player::getClient(%player); %team = Client::getTeam(%client); %extraAmmo = 0 ; if (Player::getMountedItem(%client,$BackpackSlot) == ammopack && $AmmoPackMax[%item] != "") { %extraAmmo = $AmmoPackMax[%item]; if(%delta == $ItemMax[Player::getArmor(%client), %item]) %delta = %delta + %extraAmmo; } if($TestCheats == 0 && %client.spawn == "") { %energy = $TeamEnergy[%team]; %station = %player.Station; %sName = GameBase::getDataName(%station); if(%sName == DeployableInvStation || %sName == DeployableAmmoStation){ %energy = %station.Energy; } if(%energy != "Infinite") { if (%item.price * %delta > %energy) %delta = %energy / %item.price; if(%delta < 1 ) { if(%noMessage == "") Client::sendMessage(%client,0,"Couldn't buy " @ %item.description @ " - "@ %energy @ " Energy points left"); return 0; } } } if(%item.className == Weapon) { %armor = Player::getArmor(%client); %wcount = Player::getItemClassCount(%client,"Weapon"); if (Player::getItemClassCount(%client,"Weapon") >= $MaxWeapons[%armor]) { Client::sendMessage(%client,0,"To many weapons for " @ $ArmorName[%armor].description @ " to carry"); return 0; } } else if(%item == RepairPatch) { %pDamage = GameBase::getDamageLevel(%player); if(GameBase::getDamageLevel(%player) > 0) return 1; return 0; } else if($TeamItemMax[%item] != "" && !$TestCheats) { if($TeamItemMax[%item] <= $TeamItemCount[%team, %item]) { Client::sendMessage(%client,0,"Deployable Item limit reached for " @ %item.description @ "s"); return 0; } } if(%item.className != Armor && %item.className != Vehicle) { %count = Player::getItemCount(%client,%item); %max = $ItemMax[(Player::getArmor(%client)), %item] + %extraAmmo ; if(%delta + %count >= %max) %delta = %max - %count; } return %delta; } function buyItem(%client,%item) { %player = Client::getOwnedObject(%client); %armor = Player::getArmor(%client); if (($ServerCheats || Client::isItemShoppingOn(%client,%item) || $TestCheats || %client.spawn) && ($ItemMax[%armor, %item] || %